from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]/'src/HoTroDuLich.Web'
def edit(path,fn):
 p=root/path;p.write_text(fn(p.read_text(encoding='utf-8')),encoding='utf-8')
edit('Views/Provider/Index.cshtml',lambda s:re.sub(r'@if\(p.TrangThaiQuyenHoatDong=="DangHoatDong"\)\{<form action="/Provider/Reception".*?</form>\}', '',s,flags=re.S))
edit('Views/Provider/Edit.cshtml',lambda s:s.replace('<option value="Lưu trú">Lưu trú</option><option value="Ăn uống">Ăn uống</option><option value="Phương tiện">Phương tiện</option><option value="Hoạt động">Hoạt động</option>', '@foreach(var type in DanhMuc.LoaiDichVu){<option value="@type">@DanhMuc.Ten(type)</option>}').replace('<div class="field"><label asp-for="Price">','<div class="field"><label asp-for="PlaceId">Địa điểm liên quan (tùy chọn)</label><select class="form-select" asp-for="PlaceId"><option value="">Không gắn địa điểm</option>@foreach(var place in (ViewBag.Places as List<DiaDiemDuLich>??[])){<option value="@place.MaDiaDiem">@place.TenDiaDiem</option>}</select></div><div class="field"><label asp-for="Price">').replace('<button class="btn btn-dark" type="submit">Gửi xét duyệt ↗</button>','<button class="btn btn-dark" type="submit" name="Operation" value="GuiDang" disabled="@(history.Any(x=>x.TrangThaiDuyet=="ChoDuyet"))">Gửi xét duyệt ↗</button>@if(history.Count==0){<button class="btn btn-outline" type="submit" name="Operation" value="LuuNhap">Lưu bản nháp</button>}'))
edit('Views/Companions/Edit.cshtml',lambda s:s.replace('<option value="Nghỉ dưỡng">Nghỉ dưỡng</option><option value="Khám phá">Khám phá</option><option value="Phượt">Phượt</option>','<option value="">Chưa chọn</option>@foreach(var style in DanhMuc.HinhThucDi){<option value="@style">@DanhMuc.Ten(style)</option>}').replace('Đăng bài ↗','Xem trước bài đăng ↗'))
edit('Views/Companions/Index.cshtml',lambda s:s.replace('new[]{"Nghỉ dưỡng","Khám phá","Phượt"}','DanhMuc.HinhThucDi').replace('>@style</option>','>@DanhMuc.Ten(style)</option>').replace('@n.HinhThucDi','@DanhMuc.Ten(n.HinhThucDi)').replace('@need.HinhThucDi','@DanhMuc.Ten(need.HinhThucDi)'))
edit('Views/Support/Create.cshtml',lambda s:s.replace('<input id="field-Type-1" class="form-control" name="Type" type="text" required maxlength="50" placeholder="Thời tiết, di chuyển, dịch vụ…"/>','<select id="field-Type-1" class="form-select" asp-for="Type">@foreach(var type in DanhMuc.LoaiTinhHuong){<option value="@type">@DanhMuc.Ten(type)</option>}</select>').replace('<select id="field-ActivityId-4" name="ActivityId" class="form-select"><option value="">Không gắn hoạt động</option>','<select id="field-ActivityId-4" name="ActivityIds" class="form-select" multiple aria-describedby="activities-help">').replace('</select></div><div class="form-actions">','</select><small id="activities-help">Có thể chọn nhiều hoạt động bị ảnh hưởng.</small></div><div class="form-actions">'))
edit('Views/Support/Detail.cshtml',lambda s:s.replace('@Model.LoaiTinhHuong','@DanhMuc.Ten(Model.LoaiTinhHuong)').replace('<button class="btn btn-outline" name="Decision" value="GiaiQuyetMotPhan"','<button class="btn btn-outline" name="Decision" value="ChuaGiaiQuyet" type="submit">Chưa giải quyết</button><button class="btn btn-outline" name="Decision" value="GiaiQuyetMotPhan"'))
edit('Views/Plans/Detail.cshtml',lambda s:s.replace('@foreach(var day in activities.GroupBy(x=>x.Ngay))','@foreach(var day in Enumerable.Range(0,days).Select(offset=>Model.NgayBatDau.AddDays(offset)))').replace('day.Key','day').replace('@foreach(var a in day)','@if(!activities.Any(x=>x.Ngay==day)){<p class="help">Ngày này chưa có hoạt động. Bạn có thể dành thời gian nghỉ ngơi hoặc thêm điểm dừng mới.</p>}@foreach(var a in activities.Where(x=>x.Ngay==day))').replace(' <div class="stats">',' <form action="/Plans/Decision" method="post">@Html.AntiForgeryToken()<input type="hidden" name="Id" value="@Model.MaKeHoach"/><input type="hidden" name="Version" value="@TravelService.Token(Model.RowVersion)"/><div class="form-actions"><button class="btn btn-dark" name="Decision" value="DaChapNhan" type="submit">Xác nhận lịch trình</button><button class="btn btn-outline" name="Decision" value="Nhap" type="submit">Lưu trạng thái nháp</button></div></form><div class="stats">').replace('<div class="actions"><a class="btn btn-outline btn-small" href="/Plans/Activity/','<div class="actions"><form action="/Plans/Reorder" method="post">@Html.AntiForgeryToken()<input type="hidden" name="Id" value="@a.MaHoatDong"/><input type="hidden" name="planId" value="@Model.MaKeHoach"/><input type="hidden" name="Version" value="@TravelService.Token(Model.RowVersion)"/><button class="btn btn-outline btn-small" name="Decision" value="Len" type="submit" aria-label="Chuyển hoạt động lên">↑</button><button class="btn btn-outline btn-small" name="Decision" value="Xuong" type="submit" aria-label="Chuyển hoạt động xuống">↓</button></form><a class="btn btn-outline btn-small" href="/Plans/Activity/'))
def admin(s):
 start=s.find('<form action="/Admin/Rights"');end=s.find('</form>',start)
 if start>=0:s=s[:start]+'<form action="/quan-tri/quyen-hoat-dong/xem-he-qua" method="get"><input type="hidden" name="maNCC" value="@p.MaNhaCungCap"/><div class="field"><label for="rights-operation">Thao tác</label><select id="rights-operation" class="form-select" name="thaoTac">@if(p.TrangThaiQuyenHoatDong=="DangHoatDong"){<option value="TamDinhChi">Tạm đình chỉ</option>}@if(p.TrangThaiQuyenHoatDong=="TamDinhChi"){<option value="KhoiPhuc">Khôi phục</option>}<option value="ThuHoi">Thu hồi</option></select></div><div class="form-actions"><button class="btn btn-outline" type="submit">Xem hệ quả trước khi quyết định</button></div></form>'+s[end+7:]
 return s
edit('Views/Admin/Provider.cshtml',admin)
edit('wwwroot/js/site.js',lambda s:s.replace("['Organization','Address','Phone']","['Organization','Address','OrganizationType','ContactName','ContactPhone','ContactEmail','RegistrationDescription','Representative','Documents']"))
edit('Services/Ui.cs',lambda s:s.replace('s.LoaiDichVu == "Lưu trú"','DanhMuc.ChuanHoa(s.LoaiDichVu) == "LuuTru"').replace('s.LoaiDichVu == "Ăn uống"','DanhMuc.ChuanHoa(s.LoaiDichVu) == "AnUong"').replace('type switch { "Lưu trú" => "bed", "Ăn uống" => "food", "Phương tiện" => "car", "Hoạt động" => "compass",','DanhMuc.ChuanHoa(type) switch { "LuuTru" => "bed", "AnUong" => "food", "PhuongTien" => "car", "HoatDong" => "compass",'))
print('Updated FullText workflow controls and fixed catalogs.')
